#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Values this wizard keeps: steam/steam.env (app ID, dates, which stages are done).
# None of them is secret. Run from anywhere: the paths are the repo's.
cd "$(dirname "$0")/.."
ENV_FILE="${STEAM_ENV_FILE:-steam/steam.env}"
mkdir -p "$(dirname "$ENV_FILE")"

DOCS="https://partner.steamgames.com/doc"

# already_done KEY succeeds (skip the stage) when an earlier run marked it done
# and the human does not want to go through it again.
already_done() {
  [[ "$(_existing "$1" || true)" == yes ]] || return 1
  note "Marked done on an earlier run."
  ! confirm "Go through it again?"
}
mark_done() { write_env "$1" yes; }

# ask_date KEY "Prompt" asks until the answer is a real YYYY-MM-DD date.
ask_date() {
  local key="$1" prompt="$2"
  while :; do
    ask "$key" "$prompt" || return 1
    if [[ "${!key}" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]] && date -d "${!key}" >/dev/null 2>&1; then return 0; fi
    warn "Use the form $(date +%F)."
  done
}

# check_assets DIR lists every capsule and library image Steam asks for, with
# its size. Fails when a store capsule (needed for Coming Soon) is missing or wrong.
check_assets() {
  python3 -I - "$1" <<'PY'
import os, sys
from PIL import Image
d = sys.argv[1]
# file, width, height, needed for Coming Soon
spec = [
    ("header_capsule.png", 920, 430, True),
    ("small_capsule.png", 462, 174, True),
    ("main_capsule.png", 1232, 706, True),
    ("vertical_capsule.png", 748, 896, True),
    ("page_background.png", 1438, 810, False),
    ("library_capsule.png", 600, 900, False),
    ("library_header.png", 920, 430, False),
    ("library_hero.png", 3840, 1240, False),
    ("library_logo.png", 0, 0, False),
]
bad = 0
for name, w, h, needed in spec:
    p = os.path.join(d, name)
    when = "Coming Soon" if needed else "before release"
    if not os.path.exists(p):
        print(f"  {'✗' if needed else '·'} {name:22} missing ({when}: {w}x{h})" if w else f"  · {name:22} missing ({when}: 1280 wide and/or 720 tall, transparent)")
        bad += needed
        continue
    im = Image.open(p)
    iw, ih = im.size
    if name == "library_logo.png":
        ok = (iw == 1280 and ih <= 720) or (ih == 720 and iw <= 1280)
        ok = ok and ("A" in im.getbands() or "transparency" in im.info)
        want = "1280 wide and/or 720 tall, transparent"
    else:
        ok = (iw, ih) == (w, h)
        want = f"{w}x{h}"
    print(f"  {'✓' if ok else '✗'} {name:22} {iw}x{ih}" + ("" if ok else f"  wants {want}"))
    bad += needed and not ok
sys.exit(1 if bad else 0)
PY
}

# check_screenshots DIR: at least 5 images, each 16:9 and at least 1920x1080.
check_screenshots() {
  python3 -I - "$1" <<'PY'
import os, sys
from PIL import Image
d = sys.argv[1]
files = sorted(f for f in os.listdir(d) if f.lower().endswith((".png", ".jpg", ".jpeg"))) if os.path.isdir(d) else []
good = 0
for f in files:
    w, h = Image.open(os.path.join(d, f)).size
    ok = w >= 1920 and h >= 1080 and w * 9 == h * 16
    good += ok
    print(f"  {'✓' if ok else '✗'} {f}  {w}x{h}" + ("" if ok else "  wants 16:9, at least 1920x1080"))
print(f"  {good} usable of {len(files)}; Steam needs at least 5")
sys.exit(0 if good >= 5 else 1)
PY
}

run_wizard() {

TOTAL_STAGES=15

banner "Underhum: a Steam store page, up to Coming Soon"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Before you start"
say "Valve's paperwork asks for these. Have them at hand:"
step "A Steam account with Steam Guard on. It becomes your Steamworks login."
step "A legal ID (passport or ID card) for the identity check."
step "A bank account in the same name as the signup (a JDG's business account works): IBAN, SWIFT/BIC, bank address."
step "Your tax number (in Poland: NIP for a JDG, PESEL without one). The US tax form asks for it."
step "100 USD on a card or PayPal. Steam Wallet money is not accepted."
note "Valve takes 15 to 30 days to verify all this. This wizard remembers where you stopped."
ask STEAM_ENTITY "Sign up as an individual or a company? (individual/company):"
write_env STEAM_ENTITY "$STEAM_ENTITY"
ask STEAM_DEVELOPER "Developer name to show on the store page (your name or a studio name):"
write_env STEAM_DEVELOPER "$STEAM_DEVELOPER"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Join Steamworks"
if ! already_done DONE_SIGNUP; then
  open_url "https://partner.steamgames.com/newpartner/?signup_type=1"
  step "Sign in with your Steam account."
  step "Choose: $STEAM_ENTITY. Enter your legal name and address exactly as on your ID."
  step "Read and sign the Steam Distribution Agreement."
  note "Button names on Valve's pages may differ from these words; follow the onboarding's own order."
  pause "Press Enter once the agreement is signed."
  mark_done DONE_SIGNUP
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Pay the Steam Direct fee"
if ! already_done DONE_FEE; then
  say "One 100 USD fee buys one app. It is not refundable. Valve pays it back"
  say "once the game earns 1,000 USD on Steam."
  warn "Your first game can be released at the earliest 30 days after this payment."
  open_url "https://partner.steamgames.com/steamdirect"
  if confirm "Do you already have an unused app credit, or an unreleased app Valve lets you reuse?"; then
    note "Then no new fee. In stage 7, create the app from the credit, or enter the old app's ID."
    mark_done DONE_FEE
  elif confirm "Pay the 100 USD fee now?"; then
    step "Follow the fee step in the Steamworks onboarding and pay."
    pause "Press Enter once the payment went through."
    ask_date STEAM_FEE_PAID "Date paid (YYYY-MM-DD, e.g. $(date +%F)):"
    write_env STEAM_FEE_PAID "$STEAM_FEE_PAID"
    write_env STEAM_EARLIEST_BY_FEE "$(date -d "$STEAM_FEE_PAID + 30 days" +%F)"
    mark_done DONE_FEE
  else
    SKIPPED+=("the Steam Direct fee: run the wizard again when you are ready to pay")
    finish; exit 0
  fi
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Bank details"
if ! already_done DONE_BANK; then
  open_url "https://partner.steamgames.com/"
  step "Open the bank (payment) information step of the onboarding."
  step "Enter the IBAN, SWIFT/BIC and the bank's address."
  warn "The account holder must be the same person or company as the legal ID."
  pause "Press Enter once the bank details are saved."
  mark_done DONE_BANK
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Tax interview"
if ! already_done DONE_TAX; then
  say "A questionnaire that fills the US tax form for you. A person or a sole"
  say "proprietorship (a JDG) gets a W-8BEN; a separate company (sp. z o.o.) a W-8BEN-E."
  say "It sets how much US tax is held back from your sales."
  open_url "https://partner.steamgames.com/"
  step "Open the tax information step and answer the questions."
  step "Claim the tax treaty between your country and the US when it asks; it needs your tax number."
  pause "Press Enter once the tax interview is submitted."
  mark_done DONE_TAX
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Identity check, then wait for Valve"
if ! already_done DONE_VERIFIED; then
  open_url "https://partner.steamgames.com/"
  step "Finish the identity verification step if the onboarding still lists it."
  say "Valve now checks the paperwork, bank and tax details: 15 to 30 days."
  say "Meanwhile, the screenshot and art stages (11 and 12) need no Steamworks access."
  if confirm "Has Valve finished, so the Steamworks dashboard lets you create an app?"; then
    mark_done DONE_VERIFIED
  else
    note "Meanwhile: screenshots with tools/steam_capture.sh into steam/screenshots/,"
    note "and this art in steam/assets/ (each run checks what is there):"
    mkdir -p steam/assets
    check_assets steam/assets || true
    SKIPPED+=("Valve's verification: run tools/steam_page.sh again once Steamworks lets you in")
    finish; exit 0
  fi
fi

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Create the app"
if ! already_done DONE_APP; then
  open_url "https://partner.steamgames.com/"
  step "On the Steamworks home page, create a new app with your Steam Direct credit."
  note "Reusing an old unreleased app instead? Skip creating one and enter its App ID below."
  step "Name it: Underhum"
  step "You land on the app's page. Its address ends in /apps/landing/<number>: that number is the App ID."
  while :; do
    ask STEAM_APP_ID "App ID:"
    [[ "$STEAM_APP_ID" =~ ^[0-9]+$ ]] && break
    warn "The App ID is a number, like 3123450."
  done
  write_env STEAM_APP_ID "$STEAM_APP_ID"
  mark_done DONE_APP
fi
LANDING="https://partner.steamgames.com/apps/landing/${STEAM_APP_ID:-$(_existing STEAM_APP_ID || true)}"

if [[ "$(_existing DONE_BASIC || true)" != yes ]]; then
  say "The app exists, and with it an empty store page. Only you can see it until"
  say "Valve approves it and you post it as Coming Soon."
  if ! confirm "Fill in the store page now?"; then
    SKIPPED+=("the store page: run tools/steam_page.sh again to fill it in (it starts at Basic Info)")
    finish; exit 0
  fi
fi

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Store page: basic info"
if ! already_done DONE_BASIC; then
  open_url "$LANDING"
  step "Click 'Edit Store Page', then the Basic Info tab."
  step "Developer and publisher: $(_existing STEAM_DEVELOPER || true)"
  step "Genres: Indie, Adventure, Casual. Tags: see steam/store_text.md (up to 20)."
  step "Supported OS: Windows and SteamOS + Linux. Add macOS only once a Mac build is tested."
  step "Languages: English, interface. Controller support: none (the game needs a mouse)."
  note "Fields marked * must be filled before review. Save the tab."
  pause "Press Enter once Basic Info is saved."
  mark_done DONE_BASIC
fi

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Store page: description"
if ! already_done DONE_DESC; then
  say "The draft text is in steam/store_text.md. Edit it to what ships."
  open_url "$LANDING"
  step "In Edit Store Page, open the Description tab."
  step "Paste the short description (under 300 characters) and the 'About this game' text."
  warn "No links to other websites, no Steam-looking buttons, no other games in the text."
  warn "List only what the game has at launch, or label it as planned."
  pause "Press Enter once the description is saved."
  mark_done DONE_DESC
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Content survey"
if ! already_done DONE_SURVEY; then
  open_url "$LANDING"
  open_url "$DOCS/gettingstarted/contentsurvey"
  step "From the app's page, open the Content Survey (in the release checklist)."
  step "General and mature content: answer for the cave game (no violence, no sexual content)."
  step "Generative AI: tick pre-generated. Retro Diffusion made the first drafts of the decor sprites."
  step "Paste the AI paragraph from steam/store_text.md, after checking which art it covers."
  note "No AI content is made while the game runs, so leave live-generated off."
  pause "Press Enter once the survey is submitted."
  mark_done DONE_SURVEY
fi

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Screenshots"
if ! already_done DONE_SHOTS; then
  say "Steam wants at least 5 gameplay screenshots, 16:9 and at least 1920x1080."
  say "Gameplay only: no concept art, no awards, no marketing words."
  step "Record play at 1920x1080 in another terminal:  tools/steam_capture.sh"
  note "It writes every frame to steam/capture/<time>/ plus clip.mp4. Skip the first 10 s (the controls hint)."
  step "Copy the best frames to steam/screenshots/."
  while :; do
    pause "Press Enter to check steam/screenshots/."
    if check_screenshots steam/screenshots; then break; fi
    confirm "Not enough usable screenshots yet. Check again?" || { SKIPPED+=("screenshots: at least 5 in steam/screenshots"); break; }
  done
  open_url "$LANDING"
  step "Edit Store Page, Screenshots tab: upload them."
  step "Mark at least 4 as suitable for all ages, or Steam hides them in some places."
  if confirm "Are they uploaded?"; then mark_done DONE_SHOTS; else SKIPPED+=("upload the screenshots"); fi
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Capsules and library art"
if ! already_done DONE_ART; then
  open_url "$DOCS/store/assets/standard"
  say "Put the images in steam/assets/ under these names. The capsules carry key art"
  say "and the title only: no other words, no review quotes."
  mkdir -p steam/assets
  while :; do
    pause "Press Enter to check steam/assets/."
    if check_assets steam/assets; then break; fi
    confirm "A store capsule is missing or the wrong size. Check again?" || { SKIPPED+=("capsule art in steam/assets"); break; }
  done
  note "Library art (·) is only needed before release; upload it now if it is ready."
  open_url "$LANDING"
  step "Edit Store Page, Graphical Assets tab: upload each capsule, and the library art if ready."
  if confirm "Are the capsules uploaded?"; then mark_done DONE_ART; else SKIPPED+=("upload the capsules"); fi
fi

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Trailer (optional, worth it)"
if ! already_done DONE_TRAILER; then
  say "A Coming Soon page can go up without one, but it sells the game best."
  say "Gameplay first: the first seconds should show the gecko moving."
  step "Cut it from the clip.mp4 files tools/steam_capture.sh made."
  open_url "$DOCS/store/trailer"
  if confirm "Is a trailer uploaded (Edit Store Page, Trailers)?"; then mark_done DONE_TRAILER
  else note "Skipped. Add it any time; the page can be edited after it goes live."; fi
fi

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Release date and review"
if ! already_done DONE_REVIEW; then
  [[ "$(_existing DONE_SHOTS || true)" == yes ]] || warn "Screenshots are not marked uploaded (stage 11): the checklist will block the review."
  [[ "$(_existing DONE_ART || true)" == yes ]] || warn "Capsules are not marked uploaded (stage 12): the checklist will block the review."
  open_url "$LANDING"
  step "Set the release date. 'Coming soon' or a season is fine without a fixed day."
  step "On the app's page, go through the release checklist until the store page items are green."
  say "Review takes 3 to 5 business days. Valve asks for 7 business days before the day you want it live."
  if confirm "Click 'Mark as ready for review' for the store page now?"; then
    step "Click it."
    pause "Press Enter once it is submitted."
    ask_date STEAM_REVIEW_SENT "Date submitted (YYYY-MM-DD):"
    write_env STEAM_REVIEW_SENT "$STEAM_REVIEW_SENT"
    mark_done DONE_REVIEW
  else
    SKIPPED+=("submit the store page for review")
    finish; exit 0
  fi
fi

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Post as Coming Soon"
if ! already_done DONE_LIVE; then
  say "Valve answers by email and on the app's page: changes needed, or ready for release."
  if ! confirm "Has Valve approved the store page?"; then
    note "Fix what Valve asks for and submit again. Then run this wizard again."
    SKIPPED+=("Valve's store page review: run tools/steam_page.sh again once approved")
    finish; exit 0
  fi
  open_url "$LANDING"
  warn "The next click makes the page public. Wishlists start counting from it."
  if confirm "Click the green 'Post as Coming Soon' button now?"; then
    step "Click it."
    pause "Press Enter once the page is live."
    write_env STEAM_COMING_SOON "$(date +%F)"
    mark_done DONE_LIVE
  else
    SKIPPED+=("post the page as Coming Soon")
  fi
fi

if [[ "$(_existing DONE_LIVE || true)" == yes ]]; then
  by_fee=$(_existing STEAM_EARLIEST_BY_FEE || true)
  by_page=$(date -d "$(_existing STEAM_COMING_SOON) + 14 days" +%F)
  earliest=$(printf '%s\n%s\n' "$by_fee" "$by_page" | sort | tail -1)
  write_env STEAM_EARLIEST_RELEASE "$earliest"
  say "The page is public: https://store.steampowered.com/app/$(_existing STEAM_APP_ID)/"
  say "Earliest release: $earliest (30 days after the fee, 14 days of Coming Soon)."
  pause
fi

finish
}

run_wizard "$@"; exit
